<?php
require __DIR__.'/bootstrap.php'; $admin=require_permission('applications.view'); $id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT) ?: filter_input(INPUT_POST,'id',FILTER_VALIDATE_INT); if(!$id){http_response_code(400);exit('Missing application ID.');}
$allowed=['received','under_review','shortlisted','declined','withdrawn'];$error='';$success='';
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$type=(string)($_POST['action']??'');
 try {
  if($type==='status'&&in_array('applications.review',$admin['permissions'],true)){$new=(string)($_POST['status']??'');if(!in_array($new,$allowed,true))throw new RuntimeException('Choose a valid status.');$pdo=db();$pdo->beginTransaction();$s=$pdo->prepare('SELECT application_status FROM applications WHERE id=? FOR UPDATE');$s->execute([$id]);$old=$s->fetchColumn();if($old===false)throw new RuntimeException('Application not found.');$pdo->prepare('UPDATE applications SET application_status=? WHERE id=?')->execute([$new,$id]);$pdo->prepare("INSERT INTO application_reviews(application_id,admin_user_id,review_type,old_status,new_status,note) VALUES(?,?, 'status_change',?,?,?)")->execute([$id,$admin['id'],$old,$new,trim((string)($_POST['note']??''))?:null]);$pdo->commit();$success='Application status updated.';}
  elseif($type==='score'&&in_array('applications.judge',$admin['permissions'],true)){$score=filter_var($_POST['score']??null,FILTER_VALIDATE_FLOAT);if($score===false||$score<0||$score>100)throw new RuntimeException('Enter a judging score from 0 to 100.');$note=trim((string)($_POST['note']??''));db()->prepare("INSERT INTO application_reviews(application_id,admin_user_id,review_type,score,note) VALUES(?,?, 'judging',?,?)")->execute([$id,$admin['id'],$score,$note?:null]);$success='Judging score saved.';}
  elseif($type==='note'&&in_array('applications.review',$admin['permissions'],true)){$note=trim((string)($_POST['note']??''));if($note==='')throw new RuntimeException('Enter a note.');db()->prepare("INSERT INTO application_reviews(application_id,admin_user_id,review_type,note) VALUES(?,?, 'internal_note',?)")->execute([$id,$admin['id'],$note]);$success='Internal note saved.';}
  else throw new RuntimeException('You do not have permission to perform that action.');
 } catch(Throwable $e) {if(isset($pdo)&&$pdo instanceof PDO&&$pdo->inTransaction())$pdo->rollBack();$error=$e instanceof RuntimeException?$e->getMessage():'Could not save that change.';}
}
$s=db()->prepare('SELECT * FROM applications WHERE id=?');$s->execute([$id]);$app=$s->fetch();if(!$app){http_response_code(404);exit('Application not found.');}
$s=db()->prepare('SELECT * FROM group_performers WHERE application_id=? ORDER BY id');$s->execute([$id]);$performers=$s->fetchAll();
$s=db()->prepare('SELECT gc.*,gp.full_name performer_name FROM guardian_consents gc LEFT JOIN group_performers gp ON gp.id=gc.performer_id WHERE gc.application_id=? ORDER BY gc.id');$s->execute([$id]);$guardians=$s->fetchAll();
if(in_array('applications.review',$admin['permissions'],true)){$s=db()->prepare('SELECT ar.*,au.full_name reviewer_name FROM application_reviews ar JOIN admin_users au ON au.id=ar.admin_user_id WHERE ar.application_id=? ORDER BY ar.created_at DESC');$s->execute([$id]);}else{$s=db()->prepare("SELECT ar.*,au.full_name reviewer_name FROM application_reviews ar JOIN admin_users au ON au.id=ar.admin_user_id WHERE ar.application_id=? AND ar.review_type='judging' ORDER BY ar.created_at DESC");$s->execute([$id]);}$reviews=$s->fetchAll();
page_start('Application review'); ?><p><a href="index.php" class="btn secondary">← Back to applications</a></p><h1><?=h($app['registration_reference'])?></h1><p class="sub">Application detail and authorized review actions.</p><?php if($error):?><div class="error"><?=h($error)?></div><?php endif?><?php if($success):?><div class="success"><?=h($success)?></div><?php endif?><section class="box"><h2>Applicant and entry</h2><dl class="detail"><?php foreach(['applicant_full_name'=>'Applicant','date_of_birth'=>'Date of birth','age_group'=>'Age group','email'=>'Email','phone'=>'Phone','preferred_contact'=>'Contact preference','city'=>'City','region'=>'State / region','country'=>'Country','discipline'=>'Discipline','performance_type'=>'Performance type','entry_type'=>'Entry type','group_name'=>'Group name','group_size'=>'Group size','performance_title'=>'Performance title','performance_description'=>'Description','performance_language'=>'Language','duration_text'=>'Duration','originality'=>'Original','finale_arrangement'=>'Finale preference','application_status'=>'Status','submitted_at'=>'Submitted'] as $key=>$label): if($app[$key]!==null && $app[$key]!==''): ?><dt><?=h($label)?></dt><dd><?=nl2br(h((string)$app[$key]))?></dd><?php endif;endforeach ?><dt>Audition</dt><dd><?php if($app['video_method']==='link'):?><a href="<?=h($app['video_url'])?>" target="_blank" rel="noopener noreferrer">Open submitted audition link</a><?php else:?><a href="video.php?id=<?=(int)$id?>">Play uploaded audition</a> · <?=h($app['video_original_filename']??'Video')?><?php endif?></dd></dl></section>
<?php if($performers):?><section class="box"><h2>Group performers</h2><table><thead><tr><th>Name</th><th>Age group</th><th>Applicant</th></tr></thead><tbody><?php foreach($performers as $p):?><tr><td><?=h($p['full_name'])?></td><td><?=h($p['age_group'])?></td><td><?=$p['is_applicant']?'Yes':'No'?></td></tr><?php endforeach?></tbody></table></section><?php endif?>
<?php if(in_array('guardians.view',$admin['permissions'],true)&&$guardians):?><section class="box"><h2>Guardian consent · authorized staff</h2><table><thead><tr><th>Guardian</th><th>Relationship</th><th>Contact</th><th>Verification</th></tr></thead><tbody><?php foreach($guardians as $g):?><tr><td><?=h($g['guardian_full_name'])?></td><td><?=h($g['relationship'])?></td><td><?=h($g['guardian_email'])?><br><?=h($g['guardian_phone'])?></td><td><?=h($g['verification_status'])?></td></tr><?php endforeach?></tbody></table><p class="notice">Consent is pending verification. This panel does not verify guardian identity.</p></section><?php endif?>
<section class="grid"><?php if(in_array('applications.review',$admin['permissions'],true)):?><section class="box"><h2>Update status</h2><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)$id?>"><input type="hidden" name="action" value="status"><div class="field"><label>Status</label><select name="status"><?php foreach($allowed as $s):?><option value="<?=h($s)?>" <?=$app['application_status']===$s?'selected':''?>><?=h(ucwords(str_replace('_',' ',$s)))?></option><?php endforeach?></select></div><div class="field" style="margin-top:10px"><label>Optional internal note</label><textarea name="note"></textarea></div><div class="actions"><button>Save status</button></div></form></section><?php endif?>
<?php if(in_array('applications.judge',$admin['permissions'],true)):?><section class="box"><h2>Judging score</h2><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)$id?>"><input type="hidden" name="action" value="score"><div class="field"><label>Score (0–100)</label><input type="number" name="score" min="0" max="100" step="0.01" required></div><div class="field" style="margin-top:10px"><label>Judge notes</label><textarea name="note"></textarea></div><div class="actions"><button>Save score</button></div></form></section><?php endif?>
<?php if(in_array('applications.review',$admin['permissions'],true)):?><section class="box"><h2>Internal note</h2><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)$id?>"><input type="hidden" name="action" value="note"><div class="field"><label>Note (visible to authorized admin/reviewer accounts)</label><textarea name="note" required></textarea></div><div class="actions"><button>Save note</button></div></form></section><?php endif?></section>
<section class="box"><h2>Review history</h2><table><thead><tr><th>Date</th><th>Staff</th><th>Type</th><th>Details</th><th>Score</th></tr></thead><tbody><?php foreach($reviews as $r):?><tr><td><?=h($r['created_at'])?></td><td><?=h($r['reviewer_name'])?></td><td><?=h(str_replace('_',' ',$r['review_type']))?></td><td><?php if($r['review_type']==='status_change'):?><?=h((string)$r['old_status'])?> → <?=h((string)$r['new_status'])?><?php endif?> <?=nl2br(h((string)$r['note']))?></td><td><?=h((string)$r['score'])?></td></tr><?php endforeach?><?php if(!$reviews):?><tr><td colspan="5">No review actions recorded yet.</td></tr><?php endif?></tbody></table></section><?php page_end();
